/* Release files are generated by build-prototype.cjs. */
const PREFIX='missa-offline-'+encodeURIComponent(new URL(self.registration.scope).pathname)+'-';
const CACHE=PREFIX+RELEASE.version;
const absolute=u=>new URL(u,self.registration.scope).href;
async function populate(cache){
  for(const asset of RELEASE.assets){
   const response=await fetch(absolute(asset.url),{cache:'no-store'});
   if(!response.ok||response.redirected||response.type==='opaque')throw Error('Asset unavailable');
   const digest=await crypto.subtle.digest('SHA-256',await response.clone().arrayBuffer());
   const hex=[...new Uint8Array(digest)].map(v=>v.toString(16).padStart(2,'0')).join('');
   if(hex!==asset.sha256)throw Error('Release integrity mismatch');
   await cache.put(absolute(asset.url),response);
  }
}
self.addEventListener('install',event=>event.waitUntil((async()=>{
 const cache=await caches.open(CACHE);
 try{
  await populate(cache);
 }catch(error){await caches.delete(CACHE);throw error;}
 // Activate only after the complete release has passed integrity checks.
 await self.skipWaiting();
})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{
 const history=await caches.open(PREFIX+'history');const key=absolute('__release_history__');let previous=[];
 try{previous=await (await history.match(key)).json();if(!Array.isArray(previous))previous=[];}catch{}
 const names=await caches.keys();const existing=new Set(names);const keep=[CACHE,...previous.filter(n=>n!==CACHE&&existing.has(n))].slice(0,2);
 for(const name of names)if(name.startsWith(PREFIX)&&name!==PREFIX+'history'&&!keep.includes(name)&&!name.endsWith('-repair'))await caches.delete(name);
 await history.put(key,new Response(JSON.stringify(keep),{headers:{'Content-Type':'application/json'}}));await self.clients.claim();
})()));
self.addEventListener('message',event=>{
 if(event.data?.type==='ACTIVATE_UPDATE')event.waitUntil(self.skipWaiting());
 if(event.data?.type==='STATUS')event.waitUntil((async()=>{const cache=await caches.open(CACHE);const keys=new Set((await cache.keys()).map(r=>r.url));event.ports[0]?.postMessage({version:RELEASE.version,first:RELEASE.first,last:RELEASE.last,ready:RELEASE.assets.every(a=>keys.has(absolute(a.url))),externalHymnsSaved:false});})());
 if(event.data?.type==='REPAIR')event.waitUntil((async()=>{const staging=CACHE+'-repair';try{await caches.delete(staging);const temporary=await caches.open(staging);await populate(temporary);const target=await caches.open(CACHE);for(const request of await temporary.keys())await target.put(request,await temporary.match(request));event.ports[0]?.postMessage({ok:true});}catch{event.ports[0]?.postMessage({ok:false});}finally{await caches.delete(staging);}})());
});
self.addEventListener('fetch',event=>{
 if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;
 const url=new URL(event.request.url);
 const index=absolute('index.html');
 const known=RELEASE.assets.some(a=>absolute(a.url)===url.origin+url.pathname);
 const appNavigation=event.request.mode==='navigate'&&(url.origin+url.pathname===index||url.href.split('?')[0]===self.registration.scope);
 if(!known&&!appNavigation)return;
 event.respondWith((async()=>{const cache=await caches.open(CACHE);const hit=await cache.match(appNavigation?index:url.origin+url.pathname);return hit||fetch(event.request);})());
});
